// GetVendorOrders is the resolver for the getVendorOrders field.
func (r *queryResolver) GetVendorOrders(ctx context.Context) ([]*model.Order, error) {
	var orders []*model.Order
	// Retrieve the vendor (user) ID from the context
	VendorIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get vendor ID: %v", err)
	}

	userUUID, err := uuid.Parse(*VendorIDStr)
	if err != nil {
		return nil, fmt.Errorf("invalid user ID: %w", err)
	}

	// Calculate the timestamp for 6 hours ago
	sixHoursAgo := time.Now().Add(-6 * time.Hour)

	// First, find order IDs that contain products from this vendor
	// This requires a subquery approach
	subQuery := r.DB.Table("cart_items").
		Joins("JOIN products ON cart_items.product_id = products.id").
		Where("products.vendor_id = ?", userUUID).
		Select("cart_items.order_id")

	// Then get those orders with their items
	if err := r.DB.Preload("Items.Product").
		Where("orders.id IN (?) AND orders.created_at >= ?", subQuery, sixHoursAgo).
		Find(&orders).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch vendor orders: %w", err)
	}

	return orders, nil
}

